CREATE TABLE "measurement_opportunities" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "local_revision" INTEGER NOT NULL DEFAULT 1, "measurement_run_id" TEXT NOT NULL REFERENCES motivation_measurement_runs (id) ON DELETE CASCADE, "permit_id" TEXT NOT NULL REFERENCES research_participation_permits (id), "entry_attempt_id" TEXT NOT NULL, "assigned_treatment" TEXT NOT NULL, "effective_presentation" TEXT NOT NULL, "opened_at_utc_ms" INTEGER NOT NULL, "presented_event_id" TEXT NULL REFERENCES events_v2 (event_id), "presented_at_utc_ms" INTEGER NULL, "learning_session_id" TEXT NULL REFERENCES learning_sessions (id), "learning_session_started_at_utc_ms" INTEGER NULL, "is_index_session" INTEGER NOT NULL DEFAULT 0 CHECK ("is_index_session" IN (0, 1)), "closed_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "measurement_run_id", "permit_id", "entry_attempt_id"), UNIQUE ("owner_id", "learning_session_id"), CHECK (local_revision > 0 AND opened_at_utc_ms >= 0), CHECK (assigned_treatment IN ('standard', 'adventure') AND effective_presentation IN ('standard', 'adventure')), CHECK ((presented_event_id IS NULL AND presented_at_utc_ms IS NULL) OR (presented_event_id IS NOT NULL AND presented_at_utc_ms IS NOT NULL AND presented_at_utc_ms >= opened_at_utc_ms)), CHECK ((learning_session_id IS NULL AND learning_session_started_at_utc_ms IS NULL) OR (learning_session_id IS NOT NULL AND learning_session_started_at_utc_ms IS NOT NULL AND presented_event_id IS NOT NULL AND learning_session_started_at_utc_ms >= presented_at_utc_ms)), CHECK (is_index_session = 0 OR learning_session_id IS NOT NULL), CHECK (closed_at_utc_ms IS NULL OR (closed_at_utc_ms >= opened_at_utc_ms AND (presented_at_utc_ms IS NULL OR closed_at_utc_ms >= presented_at_utc_ms) AND (learning_session_started_at_utc_ms IS NULL OR closed_at_utc_ms >= learning_session_started_at_utc_ms))));
