CREATE TABLE "motivation_measurement_runs" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "local_revision" INTEGER NOT NULL DEFAULT 1, "permit_id" TEXT NOT NULL REFERENCES research_participation_permits (id), "permit_payload_sha256" TEXT NOT NULL, "assignment_id" TEXT NOT NULL REFERENCES experiment_assignments (id), "assignment_revision" INTEGER NOT NULL, "consent_version" INTEGER NOT NULL, "consent_decided_at_utc_ms" INTEGER NOT NULL, "protocol_id" TEXT NOT NULL, "protocol_version" TEXT NOT NULL, "protocol_revision" INTEGER NOT NULL, "treatment" TEXT NOT NULL, "instrument_id" TEXT NOT NULL, "instrument_version" TEXT NOT NULL, "instrument_revision" INTEGER NOT NULL, "instrument_checksum_sha256" TEXT NOT NULL, "form_id" TEXT NOT NULL, "form_version" TEXT NOT NULL, "item_catalog_version" TEXT NOT NULL, "scoring_rule_version" TEXT NOT NULL, "app_version" TEXT NOT NULL, "build_id" TEXT NOT NULL, "database_schema_version" INTEGER NOT NULL, "content_revision" TEXT NOT NULL, "evidence_policy_version" TEXT NOT NULL, "catalog_version" TEXT NOT NULL, "state" TEXT NOT NULL, "started_at_utc_ms" INTEGER NOT NULL, "closed_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "assignment_id", "protocol_id", "protocol_version"), CHECK (local_revision > 0 AND assignment_revision > 0 AND protocol_revision > 0 AND instrument_revision > 0), CHECK (consent_version > 0 AND consent_decided_at_utc_ms >= 0 AND database_schema_version > 0), CHECK (length(permit_payload_sha256) = 64 AND permit_payload_sha256 NOT GLOB '*[^0-9a-f]*'), CHECK (length(instrument_checksum_sha256) = 64 AND instrument_checksum_sha256 NOT GLOB '*[^0-9a-f]*'), CHECK (treatment IN ('standard', 'adventure')), CHECK (scoring_rule_version = 'normalized-score-v1'), CHECK (state IN ('started', 'completed', 'skipped', 'abandoned', 'withdrawn')), CHECK (started_at_utc_ms >= consent_decided_at_utc_ms), CHECK ((state = 'started' AND closed_at_utc_ms IS NULL) OR (state <> 'started' AND closed_at_utc_ms >= started_at_utc_ms AND closed_at_utc_ms IS NOT NULL)));
CREATE TABLE "motivation_responses" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "local_revision" INTEGER NOT NULL DEFAULT 1, "run_id" TEXT NOT NULL REFERENCES motivation_measurement_runs (id) ON DELETE CASCADE, "item_id" TEXT NOT NULL, "item_catalog_version" TEXT NOT NULL, "response_code" TEXT NOT NULL, "ordinal_value" INTEGER NOT NULL, "answered_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "run_id", "item_id"), CHECK (local_revision > 0 AND answered_at_utc_ms >= 0), CHECK (ordinal_value BETWEEN 0 AND 100));
