CREATE TABLE "research_participation_permits" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "local_revision" INTEGER NOT NULL DEFAULT 1, "cloud_revision" INTEGER NOT NULL DEFAULT 0, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "participant_class" TEXT NOT NULL, "age_band_code" TEXT NOT NULL, "assignment_id" TEXT NOT NULL REFERENCES experiment_assignments (id), "assigned_treatment" TEXT NOT NULL, "consent_receipt_id" TEXT NOT NULL, "guardian_permission_receipt_ref" TEXT NULL, "learner_assent_receipt_ref" TEXT NULL, "protocol_id" TEXT NOT NULL, "protocol_version" TEXT NOT NULL, "issued_at_utc_ms" INTEGER NOT NULL, "expires_at_utc_ms" INTEGER NOT NULL, "revoked_at_utc_ms" INTEGER NULL, "issuer_key_id" TEXT NOT NULL, "payload_sha256" TEXT NOT NULL, "signature" TEXT NOT NULL, PRIMARY KEY ("id"), CHECK (participant_class IN ('adult', 'minor')), CHECK (assigned_treatment IN ('standard', 'adventure')), CHECK (participant_class = 'adult' OR (guardian_permission_receipt_ref IS NOT NULL AND learner_assent_receipt_ref IS NOT NULL)), CHECK (issued_at_utc_ms >= 0 AND expires_at_utc_ms > issued_at_utc_ms), CHECK (revoked_at_utc_ms IS NULL OR revoked_at_utc_ms >= issued_at_utc_ms), CHECK (length(payload_sha256) = 64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*'));
